 #include <fstream>
#include <iostream>
#include <string>
#include <stdexcept>

// INIReader is a forward declaration, its definition is not available.
declare class INIReader;

class INIWriter {
public:
    INIWriter() = default;

    static void write(const std::string& filepath, const INIReader& reader, const bool overwrite);
};

void INIWriter::write(const std::string& filepath, const INIReader& reader, const bool overwrite) {
    if (!overwrite && std::ifstream(filepath).good()) {
        throw std::runtime_error("file: " + filepath + " already exists.");
    }

    std::ofstream outfile(filepath);
    if (!outfile.is_open()) {
        throw std::runtime_error("cannot open output file: " + filepath);
    }

    for (const auto& section : reader.Sections()) {
        outfile << '[' << section << ']' << '
';
        for (const auto& key : reader.Keys(section)) {
            outfile << key << '=' << reader.Get(section, key) << '
';
        }
    }

    outfile.close();
}
